-- MP-0036: guarded editorial content import. Deploy portrait/logo assets first.

begin;

do $$ begin
 if not exists(select 1 from public.entities where slug='bersatu' and type='party') then raise exception 'MP-0036: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='dap' and type='party') then raise exception 'MP-0036: missing or wrong parent'; end if;
 if not exists(select 1 from public.entities where slug='pkr' and type='party') then raise exception 'MP-0036: missing or wrong parent'; end if;
 if exists(select 1 from public.entities where slug in ('tan-kok-wai','wan-azizah-wan-ismail','radzi-jidin') and (type <> 'politician' or owner_id is not null)) then raise exception 'MP-0036: ownership or type conflict'; end if;
 if exists(select 1 from public.entities where type='politician' and lower(constituency) in ('cheras','bandar tun razak','putrajaya') and slug not in ('tan-kok-wai','wan-azizah-wan-ismail','radzi-jidin')) then raise exception 'MP-0036: constituency identity conflict'; end if;
 if exists(select 1 from public.milestones m join public.entities e on e.id=m.entity_id where m.import_key like 'MP-0036:%' and (m.source_type <> 'editorial' or e.slug not in ('tan-kok-wai','wan-azizah-wan-ismail','radzi-jidin') or m.import_key not like 'MP-0036:' || e.slug || ':%')) then raise exception 'MP-0036: milestone identity conflict'; end if;
end $$;

insert into public.entities (type,parent_id,slug,name,bloc,position,constituency,state,description,website,photo_path,photo_source_url,photo_credit,profile_checked_at,profile_sources) select 'politician',parent.id,'tan-kok-wai','Tan Kok Wai','government','Member of the Dewan Rakyat','Cheras','Kuala Lumpur','Tan Kok Wai represents Cheras, Kuala Lumpur, in the Dewan Rakyat. A DAP member.','https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4162','/portraits/tan-kok-wai.webp','https://www.parlimen.gov.my/images/webuser/ahli/2022/P123.jpg','Parliament of Malaysia','2026-11-09','[{"label": "Parliament · official profile", "url": "https://www.parlimen.gov.my/profile-ahli.html?uweb=dr&id=4162"}, {"label": "DAP · current Kuala Lumpur representatives", "url": "https://dapmalaysia.org/kuala-lumpur-representatives/"}]'::jsonb from public.entities parent where parent.slug='dap' on conflict (slug) do update set parent_id=excluded.parent_id,name=excluded.name,bloc=excluded.bloc,position=excluded.position,constituency=excluded.constituency,state=excluded.state,description=excluded.description,website=excluded.website,photo_path=excluded.photo_path,photo_source_url=excluded.photo_source_url,photo_credit=excluded.photo_credit,profile_checked_at=excluded.profile_checked_at,profile_sources=excluded.profile_sources where public.entities.type='politician' and public.entities.owner_id is null and ROW(public.entities.parent_id,public.entities.name,public.entities.bloc,public.entities.position,public.entities.constituency,public.entities.state,public.entities.description,public.entities.website,public.entities.photo_path,public.entities.photo_source_url,public.entities.photo_credit,public.entities.profile_checked_at,public.entities.profile_sources) IS DISTINCT FROM ROW(excluded.parent_id,excluded.name,excluded.bloc,excluded.position,excluded.constituency,excluded.state,excluded.description,excluded.website,excluded.photo_path,excluded.photo_source_url,excluded.photo_credit,excluded.profile_checked_at,excluded.profile_sources);

