luded.profile_checked_at,excluded.profile_sources);

do $$ begin if (select count(*) from public.entities where slug in ('tan-kok-wai','wan-azizah-wan-ismail','radzi-jidin') and type='politician' and owner_id is null) <> 3 then raise exception 'MP-0036: concurrent ownership or identity change'; end if; end $$;

